            new ConstraintPolyline(
                new[]
                {
                    66.77243004977831, 62.589201536046446, 104, 68.23768004967027, -4.291748464090645, 104,
                },
                2,
                false,
                true),
            new ConstraintPolyline(
                new[]
                {
                    66.2725485410412, 62.578250425788596, 108.33535624853315, 67.73780059814453, -4.302700042724609, 108.33535624853315,
                },
                2,
                false,
                true),
            new ConstraintPolyline(
                new[]
                {
                    -14.794413272836163, -5.00031706303843, 118.74076220036525, -42.10493777868626, 10.577981871333044, 118.74076220036525, -49.236200890612295, -1.923931000951839, 118.74076220036525, -32.84377649516945, -1.4360290356516288, 118.74076220036525, -41.79356859899851, -29.73437795793932, 118.74076220036525, -32.06761386023164,
                    -35.28219635704117, 118.74076220036525,
                },
                6,
                true,
                true),
        };

        GradingResult? result = PathGrader.Grade(
            vertices,
            vertexCount,
            faces,
            faceCount,
            paths,
            hardConstraints,
            out string? errorMessage);

        Assert.NotNull(result);
        Assert.True(string.IsNullOrWhiteSpace(errorMessage) || !errorMessage.Contains("failed", StringComparison.OrdinalIgnoreCase), errorMessage);

        // Regression: the path runs alongside a retaining wall and its daylight loop reaches the
        // terrain edge, so the terrain split falls back to the full-terrain CDT re-conform. That
        // re-conform must re-insert the wall breaklines as constraints — otherwise it flips away the
        // near-vertical wall-face edges and orphans every wall-top vertex into a tent-pole spike.
        // A clean wall enclosure has zero tent-poles (a vertex whose Z differs from ALL neighbors
        // by more than 2.0) in the wall region.
        int spikes = CountTentPoles(result!.Vertices, result.VertexCount, result.Faces, result.FaceCount,
            xMin: 0, xMax: 70, yMin: -80, yMax: 55, threshold: 2.0);
        Assert.True(spikes == 0, $"Retaining-wall region has {spikes} tent-pole spikes (expected 0).");
    }

    private static int CountTentPoles(double[] v, int vc, int[] f, int fc,
        double xMin, double xMax, double yMin, double yMax, double threshold)
    {
        var adj = new System.Collections.Generic.Dictionary<int, System.Collections.Generic.HashSet<int>>();
        void Link(int a, int b)
        {
            if (!adj.TryGetValue(a, out var s)) { s = new System.Collections.Generic.HashSet<int>(); adj[a] = s; }
            s.Add(b);
        }
        for (int i = 0; i < fc; i++)
        {
            int a = f[i * 3], b = f[i * 3 + 1], c = f[i * 3 + 2];
            Link(a, b); Link(b, a); Link(b, c); Link(c, b); Link(c, a); Link(a, c);
        }
        int count = 0;
        for (int i = 0; i < vc; i++)
        {
            double x = v[i * 3], y = v[i * 3 + 1], z = v[i * 3 + 2];
            if (x < xMin || x > xMax || y < yMin || y > yMax) continue;
            if (!adj.TryGetValue(i, out var ns) || ns.Count == 0) continue;
            double up = double.MaxValue, dn = double.MaxValue;
            foreach (int j in ns)
            {
                double nz = v[j * 3 + 2];
                up = System.Math.Min(up, z - nz);   // smallest rise above a neighbor
                dn = System.Math.Min(dn, nz - z);   // smallest drop below a neighbor
            }
            if (up > threshold || dn > threshold) count++;
        }
        return count;
    }
